
const TEX_DATA = {
  "sun": "data:image/jpeg;base64,",
  "mercury": "data:image/jpeg;base64,",
  "venus": "data:image/jpeg;base64,",
  "earth": "data:image/jpeg;base64,",
  "earthclouds": "data:image/png;base64,",
  "moon": "data:image/jpeg;base64,",
  "mars": "data:image/jpeg;base64,",
  "phobos": "data:image/jpeg;base64,",
  "deimos": "data:image/jpeg;base64,",
  "jupiter": "data:image/jpeg;base64,",
  "io": "data:image/jpeg;base64,",
  "europa": "data:image/jpeg;base64,",
  "ganymede": "data:image/jpeg;base64,",
  "callisto": "data:image/jpeg;base64,",
  "saturn": "data:image/jpeg;base64,",
  "saturnring": "data:image/png;base64,",
  "titan": "data:image/jpeg;base64,",
  "rhea": "data:image/jpeg;base64,",
  "uranus": "data:image/jpeg;base64,",
  "titania": "data:image/jpeg;base64,",
  "oberon": "data:image/jpeg;base64,",
  "neptune": "data:image/jpeg;base64,",
  "triton": "data:image/jpeg;base64,",
  "background": "data:image/jpeg;base64,",
};

// ================= Scene / camera / renderer =================
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(55, window.innerWidth/window.innerHeight, 0.1, 10000);
camera.position.set(0, 100, 240);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputEncoding = THREE.sRGBEncoding;
document.body.appendChild(renderer.domElement);

const controls = new THREE.OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.minDistance = 3;
controls.maxDistance = 2500;

// ================= Loading (textures are embedded, so this resolves fast) =================
const loader = new THREE.TextureLoader();
const loadFill = document.getElementById('loadFill');
const allKeys = Object.keys(TEX_DATA);
let loadedCount = 0;
function loadTex(key) {
  const t = loader.load(TEX_DATA[key], () => {
    loadedCount++;
    loadFill.style.width = Math.round((loadedCount / allKeys.length) * 100) + '%';
    if (loadedCount >= allKeys.length) {
      document.getElementById('loadingScreen').style.display = 'none';
    }
  });
  t.encoding = THREE.sRGBEncoding;
  return t;
}

// ================= Starfield background =================
const bgGeo = new THREE.SphereGeometry(1800, 64, 64);
const bgMat = new THREE.MeshBasicMaterial({ map: loadTex("background"), side: THREE.BackSide, fog: false });
scene.add(new THREE.Mesh(bgGeo, bgMat));

// ================= Lighting =================
const sunLight = new THREE.PointLight(0xffffff, 3.2, 0, 0);
scene.add(sunLight);
scene.add(new THREE.AmbientLight(0x404040, 0.35));

// ================= Sun =================
const sun = new THREE.Mesh(
  new THREE.SphereGeometry(10, 48, 48),
  new THREE.MeshBasicMaterial({ map: loadTex("sun") })
);
scene.add(sun);

// glow sprite for the sun
const glowCanvas = document.createElement('canvas');
glowCanvas.width = glowCanvas.height = 256;
const gctx = glowCanvas.getContext('2d');
const grad = gctx.createRadialGradient(128,128,0,128,128,128);
grad.addColorStop(0, 'rgba(255,220,120,0.9)');
grad.addColorStop(1, 'rgba(255,220,120,0)');
gctx.fillStyle = grad;
gctx.fillRect(0,0,256,256);
const glowTex = new THREE.CanvasTexture(glowCanvas);
const glowSprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTex, transparent: true, depthWrite: false }));
glowSprite.scale.set(50, 50, 1);
scene.add(glowSprite);

// ================= Planet + moon data =================
const planetData = [
  { name: "Mercury", radius: 1.0, distance: 22, texture: "mercury",
    orbitSpeed: 4.15, rotSpeed: 0.005, tilt: 0.03, moons: [] },

  { name: "Venus", radius: 1.8, distance: 30, texture: "venus",
    orbitSpeed: 1.62, rotSpeed: 0.002, tilt: 3.10, moons: [] },

  { name: "Earth", radius: 1.9, distance: 40, texture: "earth",
    cloudsTexture: "earthclouds",
    orbitSpeed: 1.00, rotSpeed: 0.03, tilt: 0.41,
    moons: [ { name: "Moon", radius: 0.5, distance: 3.6, texture: "moon", orbitSpeed: 3.0 } ] },

  { name: "Mars", radius: 1.3, distance: 50, texture: "mars",
    orbitSpeed: 0.53, rotSpeed: 0.029, tilt: 0.44,
    moons: [
      { name: "Phobos", radius: 0.12, distance: 2.0, texture: "phobos", orbitSpeed: 6.0 },
      { name: "Deimos", radius: 0.09, distance: 2.7, texture: "deimos", orbitSpeed: 3.5 }
    ] },

  { name: "Jupiter", radius: 6.5, distance: 74, texture: "jupiter",
    orbitSpeed: 0.084, rotSpeed: 0.12, tilt: 0.05,
    moons: [
      { name: "Io",       radius: 0.35, distance: 9.5,  texture: "io",       orbitSpeed: 2.6 },
      { name: "Europa",   radius: 0.32, distance: 11.2, texture: "europa",   orbitSpeed: 2.1 },
      { name: "Ganymede", radius: 0.45, distance: 13.2, texture: "ganymede", orbitSpeed: 1.6 },
      { name: "Callisto", radius: 0.42, distance: 15.4, texture: "callisto", orbitSpeed: 1.1 }
    ] },

  { name: "Saturn", radius: 5.5, distance: 100, texture: "saturn",
    ring: { texture: "saturnring", inner: 7.5, outer: 13 },
    orbitSpeed: 0.034, rotSpeed: 0.11, tilt: 0.47,
    moons: [
      { name: "Titan", radius: 0.5, distance: 16, texture: "titan", orbitSpeed: 0.9 },
      { name: "Rhea",  radius: 0.2, distance: 12, texture: "rhea",  orbitSpeed: 1.3 }
    ] },

  { name: "Uranus", radius: 3.6, distance: 124, texture: "uranus",
    orbitSpeed: 0.012, rotSpeed: 0.07, tilt: 1.71,
    moons: [
      { name: "Titania", radius: 0.22, distance: 7, texture: "titania", orbitSpeed: 1.4 },
      { name: "Oberon",  radius: 0.2,  distance: 9, texture: "oberon",  orbitSpeed: 1.0 }
    ] },

  { name: "Neptune", radius: 3.5, distance: 146, texture: "neptune",
    orbitSpeed: 0.006, rotSpeed: 0.065, tilt: 0.49,
    moons: [
      { name: "Triton", radius: 0.3, distance: 7.5, texture: "triton", orbitSpeed: -1.1 }
    ] },
];

const planets = [];

planetData.forEach(p => {
  const orbitGeo = new THREE.RingGeometry(p.distance - 0.05, p.distance + 0.05, 128);
  const orbitMat = new THREE.MeshBasicMaterial({ color: 0x666666, side: THREE.DoubleSide, transparent: true, opacity: 0.35 });
  const orbitRing = new THREE.Mesh(orbitGeo, orbitMat);
  orbitRing.rotation.x = Math.PI / 2;
  orbitRing.userData.isOrbitLine = true;
  scene.add(orbitRing);

  const pivot = new THREE.Object3D();
  pivot.rotation.y = Math.random() * Math.PI * 2;
  scene.add(pivot);

  const mat = new THREE.MeshStandardMaterial({ map: loadTex(p.texture), roughness: 0.85, metalness: 0.05 });
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(p.radius, 48, 48), mat);
  mesh.position.x = p.distance;
  mesh.rotation.z = p.tilt;
  pivot.add(mesh);

  if (p.cloudsTexture) {
    const cloudMat = new THREE.MeshStandardMaterial({
      map: loadTex(p.cloudsTexture), transparent: true, opacity: 0.55, depthWrite: false
    });
    const clouds = new THREE.Mesh(new THREE.SphereGeometry(p.radius * 1.02, 48, 48), cloudMat);
    mesh.add(clouds);
    mesh.userData.clouds = clouds;
  }

  if (p.ring) {
    const ringGeo = new THREE.RingGeometry(p.ring.inner, p.ring.outer, 128);
    const uv = ringGeo.attributes.uv;
    const posAttr = ringGeo.attributes.position;
    for (let i = 0; i < posAttr.count; i++) {
      const x = posAttr.getX(i), y = posAttr.getY(i);
      const r = Math.sqrt(x*x + y*y);
      const t = (r - p.ring.inner) / (p.ring.outer - p.ring.inner);
      uv.setXY(i, t, 1);
    }
    const ringMat = new THREE.MeshBasicMaterial({
      map: loadTex(p.ring.texture), side: THREE.DoubleSide, transparent: true, opacity: 0.9
    });
    const ringMesh = new THREE.Mesh(ringGeo, ringMat);
    ringMesh.rotation.x = Math.PI / 2 - 0.4;
    mesh.add(ringMesh);
  }

  const moonMeshes = [];
  (p.moons || []).forEach(m => {
    const mPivot = new THREE.Object3D();
    mPivot.rotation.y = Math.random() * Math.PI * 2;
    mesh.add(mPivot);
    const mMat = new THREE.MeshStandardMaterial({ map: loadTex(m.texture), roughness: 0.9 });
    const mMesh = new THREE.Mesh(new THREE.SphereGeometry(m.radius, 20, 20), mMat);
    mMesh.position.x = m.distance;
    mPivot.add(mMesh);
    moonMeshes.push({ pivot: mPivot, mesh: mMesh, data: m });
  });

  planets.push({ mesh, pivot, data: p, moons: moonMeshes });
});

// ================= Asteroid belt (instanced, between Mars & Jupiter) =================
const ASTEROID_COUNT = 2500;
const asteroidGeo = new THREE.IcosahedronGeometry(0.14, 0);
const asteroidMat = new THREE.MeshStandardMaterial({ color: 0x8a8378, roughness: 1.0 });
const asteroidBelt = new THREE.InstancedMesh(asteroidGeo, asteroidMat, ASTEROID_COUNT);
const dummy = new THREE.Object3D();
const beltInnerR = 58, beltOuterR = 68;
for (let i = 0; i < ASTEROID_COUNT; i++) {
  const r = beltInnerR + Math.random() * (beltOuterR - beltInnerR);
  const theta = Math.random() * Math.PI * 2;
  const y = (Math.random() - 0.5) * 2.2;
  dummy.position.set(Math.cos(theta) * r, y, Math.sin(theta) * r);
  const s = 0.4 + Math.random() * 1.6;
  dummy.scale.setScalar(s);
  dummy.rotation.set(Math.random()*6, Math.random()*6, Math.random()*6);
  dummy.updateMatrix();
  asteroidBelt.setMatrixAt(i, dummy.matrix);
}
scene.add(asteroidBelt);

// ================= Raycasting for hover labels =================
const raycaster = new THREE.Raycaster();
const mouse = new THREE.Vector2();
const label = document.getElementById('planetLabel');
let labelsEnabled = true;

renderer.domElement.addEventListener('mousemove', (e) => {
  if (!labelsEnabled) { label.style.display = 'none'; return; }
  mouse.x = (e.clientX / window.innerWidth) * 2 - 1;
  mouse.y = -(e.clientY / window.innerHeight) * 2 + 1;
  raycaster.setFromCamera(mouse, camera);

  const targets = [{ mesh: sun, name: "Sun" }];
  planets.forEach(p => {
    targets.push({ mesh: p.mesh, name: p.data.name });
    p.moons.forEach(m => targets.push({ mesh: m.mesh, name: m.data.name }));
  });
  const hits = raycaster.intersectObjects(targets.map(t => t.mesh));
  if (hits.length > 0) {
    const found = targets.find(t => t.mesh === hits[0].object);
    label.style.display = 'block';
    label.style.left = (e.clientX + 14) + 'px';
    label.style.top = (e.clientY + 4) + 'px';
    label.textContent = found ? found.name : "";
    renderer.domElement.style.cursor = 'pointer';
  } else {
    label.style.display = 'none';
    renderer.domElement.style.cursor = 'default';
  }
});

// ================= UI toggles =================
let speedMultiplier = 1;
document.getElementById('speedSlider').addEventListener('input', (e) => {
  speedMultiplier = parseFloat(e.target.value);
  document.getElementById('speedVal').textContent = speedMultiplier.toFixed(1) + 'x';
});
document.getElementById('toggleOrbits').addEventListener('change', (e) => {
  scene.children.forEach(c => { if (c.userData.isOrbitLine) c.visible = e.target.checked; });
});
document.getElementById('toggleMoons').addEventListener('change', (e) => {
  planets.forEach(p => p.moons.forEach(m => m.pivot.visible = e.target.checked));
});
document.getElementById('toggleBelt').addEventListener('change', (e) => {
  asteroidBelt.visible = e.target.checked;
});
document.getElementById('toggleLabels').addEventListener('change', (e) => {
  labelsEnabled = e.target.checked;
  if (!labelsEnabled) label.style.display = 'none';
});

// ================= Resize =================
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// ================= Animation loop =================
const clock = new THREE.Clock();
function animate() {
  requestAnimationFrame(animate);
  const dt = clock.getDelta();

  sun.rotation.y += 0.0015 * speedMultiplier;

  planets.forEach(p => {
    p.pivot.rotation.y += (p.data.orbitSpeed * 0.25 * dt) * speedMultiplier;
    p.mesh.rotation.y += p.data.rotSpeed * speedMultiplier;
    if (p.mesh.userData.clouds) p.mesh.userData.clouds.rotation.y += 0.004 * speedMultiplier;
    p.moons.forEach(m => {
      m.pivot.rotation.y += (m.data.orbitSpeed * 0.5 * dt) * speedMultiplier;
    });
  });

  asteroidBelt.rotation.y += 0.0006 * speedMultiplier;

  controls.update();
  renderer.render(scene, camera);
}
animate();
